 static inline
SynchrotronRadiationRecordData OctupoleData_getp_internal_record(OctupoleData el, LocalParticle* part){
    RecordIdentifier record_id = OctupoleData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (SynchrotronRadiationRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
