 static inline
SynchrotronRadiationRecordData MagnetData_getp_internal_record(MagnetData el, LocalParticle* part){
    RecordIdentifier record_id = MagnetData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (SynchrotronRadiationRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
