/*---GENERATED GET RECORD FUNCTION---*/
 static inline
SynchrotronRadiationRecordData QuadrupoleData_getp_internal_record(QuadrupoleData el, LocalParticle* part){
    RecordIdentifier record_id = QuadrupoleData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (SynchrotronRadiationRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
